    maxLife,
    radius: tankRadius(design),
    velocity: { x: 0, y: 0 },
    guns: [],
    status: { stun: 0, jam: 0, sticky: 0, ink: 0, weaken: 0, infect: 0 },
    infectCounter: 0,
