    expect(first[4].destination).toEqual({ x: first[0].x, y: first[0].y });
    expect(proof.samples[3].tanks[2].wallAge).toBe(119);
    expect(proof.samples[3].tanks[0].x).not.toBe(first[0].x);
    expect(proof.paused).toEqual(proof.before);
    await page.locator('"'#stage').screenshot({ path: "'`test-results/${native ? '"'native' : 'mock'}-live-actor-behaviors.png"'` });
    expect(errors).toEqual([]);
  });
